def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each collection of nested parentheses
    paren_groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            current_group += char
        elif char == ")":
            current_group += char
            paren_groups.append(current_group)
            current_group = ""

    # Step 3: Check if each collection is balanced with no overlapping
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack.pop() != "(":
                    return False
        return not stack

    balanced_groups = [group for group in paren_groups if is_balanced(group)]

    # Step 4: Separate each collection into distinct strings
    distinct_groups = []
    for group in balanced_groups:
        distinct_group = ""
        for char in group:
            if char == "(":
                distinct_group += char
            elif char == ")":
                distinct_group += char
                distinct_groups.append(distinct_group)
                distinct_group = ""

    # Step 5: Return the list of distinct strings
    return distinct_groups

